import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";
// List of states and districts example
const stateDistrictData = {
  "Andhra Pradesh": ["Anantapur", "Chittoor", "East Godavari"],
  "Karnataka": ["Bangalore", "Mysore", "Mangalore"],
  "Tamil Nadu": ["Chennai", "Coimbatore", "Madurai"],
  // ...add all states and districts you need
};

export default function HomePage() {
  const navigate = useNavigate();
  const initials = "SP";

  const [selectedState, setSelectedState] = useState("");
  const [selectedDistrict, setSelectedDistrict] = useState("");
  const [city, setCity] = useState("");

  // ...all your previous JSX for navbar, hero, and prediction cards

  return (
    <div>
      {/* ...navbar and cards above unchanged... */}

      {/* --- New Search Section Below --- */}
      <div className="search-section">
        <h2>Find Properties by Location</h2>
        <div className="search-row">
          <select
            value={selectedState}
            onChange={e => {
              setSelectedState(e.target.value);
              setSelectedDistrict("");
              setCity("");
            }}
          >
            <option value="">Select State</option>
            {Object.keys(stateDistrictData).map((state) => (
              <option key={state} value={state}>{state}</option>
            ))}
          </select>
          <select
            value={selectedDistrict}
            onChange={e => {
              setSelectedDistrict(e.target.value);
              setCity("");
            }}
            disabled={!selectedState}
          >
            <option value="">Select District</option>
            {selectedState &&
              stateDistrictData[selectedState].map((dist) => (
                <option key={dist} value={dist}>{dist}</option>
              ))}
          </select>
          <input
            type="text"
            placeholder="Enter City"
            value={city}
            onChange={e => setCity(e.target.value)}
            disabled={!selectedDistrict}
          />
        </div>
      </div>

      {(city && selectedDistrict && selectedState) && (
        <div className="buy-sell-row">
          <div className="buy-sell-container">
            <h3>Sell House</h3>
            <button onClick={() => navigate("/sell-house")}>
              Sell a House in {city}, {selectedDistrict}, {selectedState}
            </button>
          </div>
          <div className="buy-sell-container">
            <h3>Buy House</h3>
            <button onClick={() => navigate("/buy-house")}>
              Buy a House in {city}, {selectedDistrict}, {selectedState}
            </button>
          </div>
          <div className="buy-sell-container">
            <h3>Sell Land</h3>
            <button onClick={() => navigate("/sell-land")}>
              Sell Land in {city}, {selectedDistrict}, {selectedState}
            </button>
          </div>
          <div className="buy-sell-container">
            <h3>Buy Land</h3>
            <button onClick={() => navigate("/buy-land")}>
              Buy Land in {city}, {selectedDistrict}, {selectedState}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
